const lookup=$input.first().json;
if(lookup.statusCode!==200 || !Array.isArray(lookup.body) || lookup.body.length!==0) throw Error('Company contact lookup did not confirm no matches');
const m=$('Freeze verified Quote plan').first().json;
const first=String(m.contact.first||'').trim(), last=String(m.contact.last||'').trim();
if(!first||!m.source) throw Error('Missing quote client name or source');
const name=last ? last+', '+first : first;
const hash=require('crypto').createHash('sha256').update('cooltech-quote-client:'+m.source).digest('hex');
const uuid=hash.slice(0,8)+'-'+hash.slice(8,12)+'-4'+hash.slice(13,16)+'-a'+hash.slice(17,20)+'-'+hash.slice(20,32);
return [{json:{uuid,name,active:1}}];

const expected=$('Prepare New Quote Client').first().json;
const {statusCode,body}=$input.first().json;
if(statusCode!==200 || body?.uuid!==expected.uuid || body.name!==expected.name || ![1,'1',true].includes(body.active)) throw Error('Quote client readback failed');
return [{json:{companyUuid:body.uuid}}];

const fallback=$('Verify New Quote Client');
const lookup=$('Search Existing Contact').first().json;
const companyUuid=fallback.isExecuted ? fallback.first().json.companyUuid : (lookup.statusCode===200 ? lookup.body?.[0]?.company_uuid : null);
if(!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(String(companyUuid||'')) || companyUuid==='00000000-0000-0000-0000-000000000000') throw Error('Quote company UUID not resolved');
return [{json:{companyUuid}}];

